import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow

/**
 * Which real-time translation provider a session talks to.
 *
 * Both providers do the same job — continuous audio in, translated text and
 * (optionally) translated speech out — but their wire protocols are unrelated:
 *
 * - [GEMINI_LIVE]  Gemini Live Translation: `setup` carries the translation
 *                  config; audio goes out as `realtimeInput.audio`.
 * - [QWEN_LIVE]    Qwen LiveTranslate: `session.update` carries the translation
 *                  config; audio goes out as `input_audio_buffer.append`.
 */
enum class TranslateProvider {
    GEMINI_LIVE,
    QWEN_LIVE,
    ;

    companion object {
        fun fromStorage(raw: String?): TranslateProvider =
            entries.firstOrNull { it.name == raw } ?: GEMINI_LIVE
    }
}

/**
 * Everything either client needs to open a session. Fields that only apply to
 * one provider are ignored by the other, which keeps a single call site in
 * [com.livetranslate.app.service.SubtitleSessionService].
 */
data class RealtimeConfig(
    val provider: TranslateProvider,
    val apiKey: String,
    val targetLanguageCode: String,
    /** Gemini Live Translate endpoint (WebSocket URL). */
    val geminiEndpoint: String = "",
    /** Gemini model id, e.g. `gemini-3.5-live-translate-preview`. */
    val geminiModelId: String = "",
    /** Gemini: echo the original when input already matches the target. */
    val echoTargetLanguage: Boolean = true,
    /** Gemini: server-issued handle that lets a reconnect continue the session. */
    val resumptionHandle: String? = null,
    /** Qwen: Model Studio workspace id used in the WebSocket host. */
    val qwenWorkspaceId: String = "",
    /** Qwen: region host part, e.g. `cn-beijing` or `ap-southeast-1`. */
    val qwenRegion: String = "cn-beijing",
    /** Qwen model id, e.g. `qwen3.8-livetranslate-flash-realtime`. */
    val qwenModelId: String = "",
    /** Qwen: source language hint; null lets the server auto-detect. */
    val qwenSourceLanguage: String? = null,
    /** Ask the service for translated speech as well as translated text. */
    val includeTranslatedAudio: Boolean = true,
)

sealed class ConnectionState {
    data object Idle : ConnectionState()
    data object Connecting : ConnectionState()
    data object Ready : ConnectionState()
    data class Failed(val message: String) : ConnectionState()
    data object Closed : ConnectionState()
}

sealed class LiveEvent {
    data class InputTranscript(val text: String, val languageCode: String? = null) : LiveEvent()
    data class OutputTranscript(val text: String, val languageCode: String? = null) : LiveEvent()
    data class AudioChunk(val pcm: ByteArray, val mimeType: String?) : LiveEvent() {
        override fun equals(other: Any?): Boolean = this === other
        override fun hashCode(): Int = pcm.contentHashCode()
    }
    data class Error(val message: String) : LiveEvent()
    data object SetupComplete : LiveEvent()
    data class Debug(val message: String) : LiveEvent()

    /** Server will terminate this connection soon; reconnect to continue. */
    data class GoAway(val timeLeftMs: Long?) : LiveEvent()
}

/**
 * Common surface implemented by both provider clients so the session service
 * can drive either one without branching on every call.
 */
interface RealtimeTranslateClient {
