/**
 * Picks the client implementation for a provider.
 *
 * Kept deliberately small: one place that knows which class speaks which
 * protocol, so the session service never branches on provider itself.
 */
object RealtimeClientFactory {
    fun create(provider: TranslateProvider): RealtimeTranslateClient = when (provider) {
        TranslateProvider.GEMINI_LIVE -> LiveTranslateClient()
        TranslateProvider.QWEN_LIVE -> QwenLiveTranslateClient()
    }
}
