import android.content.Context
import android.media.AudioDeviceCallback
import android.media.AudioDeviceInfo
import android.media.AudioManager
import android.media.AudioRecord
import android.media.AudioTrack
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.util.Log

/**
 * Routes translated speech to a Bluetooth headset and keeps capture on the
 * phone's own microphone.
 *
 * Why this exists: this app's primary use is "phone listens to the room, I
 * listen to the Chinese in my earbuds". Two Android facts shape the design.
 *
 * 1. Output. An [AudioTrack] with no preferred device follows the system's
 *    current routing, which usually *already* means a connected A2DP/BLE
 *    headset — but not reliably, and not while another app holds focus. Asking
 *    for the headset explicitly makes it deterministic. `setPreferredDevice`
 *    is a request, not a guarantee, so the actually routed device is read back
 *    and logged; that difference is real and worth surfacing.
 *
 * 2. Input. When a headset is connected, `AudioRecord` may pick the headset
 *    mic (HFP/SCO) instead of the phone mic. For listening to another speaker
 *    that is the wrong choice — headset mics are tuned for the wearer's near
 *    voice. The phone mic is preferred explicitly.
 *
 * SCO is deliberately not used: `startBluetoothSco()` is deprecated and
 * switching to SCO would move output onto the narrowband call path, hurting
 * the very audio quality this feature is for.
 */
class BluetoothAudioRoute(context: Context) {

    private val audioManager =
        context.applicationContext.getSystemService(Context.AUDIO_SERVICE) as AudioManager

    private var registered = false

    /** Called whenever the set of audio devices changes (headset plugged/lost). */
    private var onDevicesChanged: (() -> Unit)? = null

    private val deviceCallback = object : AudioDeviceCallback() {
        override fun onAudioDevicesAdded(addedDevices: Array<out AudioDeviceInfo>) {
            Log.i(TAG, "audio devices added: ${addedDevices.joinToString { it.typeName() }}")
            onDevicesChanged?.invoke()
        }

        override fun onAudioDevicesRemoved(removedDevices: Array<out AudioDeviceInfo>) {
            Log.i(TAG, "audio devices removed: ${removedDevices.joinToString { it.typeName() }}")
            onDevicesChanged?.invoke()
        }
    }

    fun start(listener: () -> Unit) {
        onDevicesChanged = listener
        if (!registered) {
            audioManager.registerAudioDeviceCallback(deviceCallback, Handler(Looper.getMainLooper()))
            registered = true
        }
    }

    fun stop() {
        if (registered) {
            runCatching { audioManager.unregisterAudioDeviceCallback(deviceCallback) }
            registered = false
        }
        onDevicesChanged = null
    }

    /**
     * Ask [track] to play through a Bluetooth headset if one is connected.
     *
     * Returns a short human-readable description of the outcome for the debug
     * log; never throws. Call this again when devices change, since a
     * preferred device that is unplugged is silently dropped.
     */
    fun preferHeadsetOutput(track: AudioTrack): String {
        val headset = findHeadsetOutput()
        if (headset == null) {
            // Leave the system default. If nothing is connected that is the
            // phone speaker, which is the sensible fallback.
            return "no Bluetooth output connected — using system default"
        }
        val accepted = runCatching { track.setPreferredDevice(headset) }.getOrDefault(false)
        val routed = runCatching { track.routedDevice }.getOrNull()
        advanceDebug("preferred=${headset.typeName()} accepted=$accepted routed=${routed?.typeName()}")
        return if (accepted) {
            "Bluetooth output requested: ${headset.typeName()}"
        } else {
            "Bluetooth output request rejected (${headset.typeName()})"
        }
    }

    private fun advanceDebug(message: String) = Log.i(TAG, message)

    /**
     * Keep microphone capture on the phone's built-in mic rather than a
     * connected headset's mic. Best-effort: if the platform refuses, capture
     * still works with whatever the default is.
     */
    fun preferBuiltInMic(record: AudioRecord): String {
        val builtIn = audioManager.getDevices(AudioManager.GET_DEVICES_INPUTS).firstOrNull {
            it.type == AudioDeviceInfo.TYPE_BUILTIN_MIC
        } ?: return "no built-in mic listed — using default input"
        val accepted = runCatching { record.setPreferredDevice(builtIn) }.getOrDefault(false)
        val routed = runCatching { record.routedDevice }.getOrNull()
        Log.i(TAG, "mic preferred accepted=$accepted routed=${routed?.typeName()}")
        return if (accepted) "phone mic requested" else "phone mic request rejected"
    }

    /** True when some Bluetooth sink is currently available for playback. */
    fun hasHeadsetOutput(): Boolean = findHeadsetOutput() != null

    fun describeOutputRoute(): String {
        val devices = audioManager.getDevices(AudioManager.GET_DEVICES_OUTPUTS)
        if (devices.isEmpty()) return "no output devices reported"
        return devices.joinToString(", ") { it.typeName() }
    }

    private fun findHeadsetOutput(): AudioDeviceInfo? {
        val devices = audioManager.getDevices(AudioManager.GET_DEVICES_OUTPUTS)
        // Preference order: LE Audio first (best quality and lowest latency),
        // then classic A2DP, then the SCO call path as a last resort.
        HEADSET_TYPES.forEach { type ->
            devices.firstOrNull { it.type == type }?.let { return it }
        }
        return null
    }

