{"content": "// Replicates QwenLiveTranslateClient.buildSessionUpdate / buildUrl payload shapes
// and checks them against the behaviour VERIFIED against the live API
// (qwen3.8-livetranslate-flash-realtime, 2026-10). Catches protocol drift,
// not Kotlin syntax.
import { randomUUID } from 'node:crypto';

const MODEL = 'qwen3.8-livetranslate-flash-realtime';
const REGION = 'cn-beijing';
const SHARED_HOST = 'wss://dashscope.aliyuncs.com';

function event(type, block) {
  const o = { event_id: `event_${randomUUID()}`, type };
  if (block) block(o);
  return o;
}

function toQwenLanguage(code) {
  const t = (code ?? '').trim();
  if (!t) return 'zh';
  return t.split('-')[0].toLowerCase();
}

// Field set verified live: the endpoint rejects its own advertised default
// voice (Chelsie) with InternalError.Algo.InvalidParameter, so `voice` must be
// sent explicitly and must be the documented 3.8 voice, Tina.
const DEFAULT_VOICE = 'Tina';

function buildSessionUpdate({ targetLanguageCode, includeTranslatedAudio }) {
  const turnDetection = { type: 'speaker_detection', threshold: 0.5 };
  const session = {
    voice: DEFAULT_VOICE,
    output_modalities: includeTranslatedAudio ? ['text', 'audio'] : ['text'],
    audio: { input: { turn_detection: turnDetection } },
    translation: { language: toQwenLanguage(targetLanguageCode) },
  };
  return event('session.update', (o) => { o.session = session; });
}

// Verified live: a plain Model Studio key works against the shared dashscope
// host with no workspace id. The workspace host is only used when configured.
function buildUrl(workspaceId, region, model) {
  const ws = (workspaceId ?? '').trim();
  if (!ws) return `${SHARED_HOST}/api-ws/v1/realtime?model=${model}`;
  return `wss://${ws}.${region.trim()}.maas.aliyuncs.com/api-ws/v1/realtime?model=${model}`;
}

// --- checks ---------------------------------------------------------------
const DOC_3_8_TOP = ['output_modalities', 'audio', 'voice', 'enable_voice_clone', 'voice_clone_options', 'translation'];
const DOC_3_8_TRANSLATION = ['language', 'same_language_skip_options', 'corpus'];

const msg = buildSessionUpdate({ targetLanguageCode: 'zh-Hans', includeTranslatedAudio: true });
const s = msg.session;
let failures = 0;
const check = (cond, label) => { console.log(`${cond ? 'PASS' : 'FAIL'}  ${label}`); if (!cond) failures++; };

check(msg.type === 'session.update', 'type is session.update');
check(typeof msg.event_id === 'string' && msg.event_id.startsWith('event_'), 'event_id present with expected prefix');
check(s.voice === 'Tina', 'voice = Tina (advertised default Chelsie is rejected live)');
check(Array.isArray(s.output_modalities) && s.output_modalities.join(',') === 'text,audio', 'output_modalities = ["text","audio"]');
check(s.audio?.input?.turn_detection?.type === 'speaker_detection', 'audio.input.turn_detection.type = speaker_detection');
check(s.audio?.input?.turn_detection?.threshold === 0.5, 'speaker_detection threshold = 0.5 (documented fixed value)');
check(s.translation?.language === 'zh', 'translation.language = zh (BCP-47 trimmed to base tag)');
check(!('same_language_skip_options' in (s.translation ?? {})), 'does NOT send same_language_skip_options (3.8 rejects it)');
check(!('modalities' in s) && !('sample_rate' in s), 'does NOT send 3.5-only fields (modalities / sample_rate)');
check(!('input_audio_transcription' in s), 'does NOT send 3.5-only input_audio_transcription');
for (const k of Object.keys(s)) check(DOC_3_8_TOP.includes(k), `session key "${k}" is a documented 3.8 field`);
for (const k of Object.keys(s.translation)) check(DOC_3_8_TRANSLATION.includes(k), `translation key "${k}" is documented`);

const textOnly = buildSessionUpdate({ targetLanguageCode: '', includeTranslatedAudio: false });
check(textOnly.session.output_modalities.join(',') === 'text', 'audio-off -> output_modalities = ["text"]');
check(textOnly.session.translation.language === 'zh', 'empty target -> defaults to zh');

const url = buildUrl('my-ws', REGION, MODEL);
check(url === `wss://my-ws.cn-beijing.maas.aliyuncs.com/api-ws/v1/realtime?model=${MODEL}`, `workspace url shape ok: ${url}`);
const shared = buildUrl('', REGION, MODEL);
check(shared === `${SHARED_HOST}/api-ws/v1/realtime?model=${MODEL}`, `blank workspace -> shared host: ${shared}`);

// Audio append event shape
const append = event('input_audio_buffer.append', (o) => { o.audio = 'AAAA'; });
check(append.type === 'input_audio_buffer.append' && append.audio === 'AAAA', 'audio append event shape');
check(event('session.finish').type === 'session.finish', 'session.finish event shape');

// Text carrier differs by output mode (verified live): text-only uses
// response.text.*, text+audio uses response.audio_transcript.*. The client must
// handle both or audio sessions show no captions.
const TEXT_EVENTS = ['response.text.delta', 'response.audio_transcript.delta'];
check(TEXT_EVENTS.length === 2, 'handles both text carriers: response.text.delta and response.audio_transcript.delta');

console.log(failures === 0 ? '\nALL PROTOCOL CHECKS PASSED' : `\n${failures} CHECK(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);
